package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import tools.jackson.databind.node.ObjectNode;

/** email-unique: — an owner whose lower-cased email is already used by another owner is rejected with 409. */
@Tag("email-unique")
class EmailUniqueTests extends AcceptanceBase {

	@Test
	void rejectsDuplicateEmailCaseInsensitively() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", "Dup.User@Example.COM");
		createOwnerOk(a);

		// A different owner (unique name/address/telephone) reusing the same email,
		// in a different case, must collide on the lower-cased email.
		ObjectNode b = ownerNode();
		b.put("email", "dup.user@example.com");
		createOwner(b).andExpect(status().isConflict());
	}

	@Test
	void allowsDistinctEmails() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", uniqueEmail());
		createOwnerOk(a);

		ObjectNode b = ownerNode();
		b.put("email", uniqueEmail());
		createOwner(b).andExpect(status().is2xxSuccessful());
	}
}

